// <diletta-divider> — a INSTÂNCIA WEB de `design-system-divider`.
//
// A primeira peça que fechou por causa de um ABSOLUTO ganhar nome. O tom
// `onColor` sempre pintou branco a 30%; o que mudou em 07/09 foi o valor passar a
// existir como `whiteAlpha30` em vez de ser calculado — e cor calculada não tem
// token para a web amarrar.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-divider';
const TONE = ['superficie', 'onColor'];
const ORIENTACAO = ['horizontal', 'vertical'];

class DilettaDivider extends HTMLElement {
  static observedAttributes = ['tone', 'orientacao', 'recuo', 'recuoFinal'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  render() {
    const tone = eixo(this, 'tone', TONE, 'superficie');
    const vertical = this.getAttribute('orientacao') === 'vertical';
    const p = papeisDe(SLUG, { Tone: tone });
    const ini = Number(this.getAttribute('recuo') || 0);
    const fim = Number(this.getAttribute('recuoFinal') || 0);

    // `role="separator"` e não uma div pintada: o leitor de tela precisa saber que
    // ali termina um grupo. E `aria-orientation` porque o default do papel é
    // horizontal — uma régua vertical sem isso é anunciada errado.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .fio {
          ${estiloDa({ bg: p.color })}
          ${vertical
            ? `width: 1px; height: 100%; margin-block: ${ini}px ${fim}px;`
            : `height: 1px; width: auto; margin-inline: ${ini}px ${fim}px;`}
        }
      </style>
      <div class="fio" part="fio" role="separator"
           ${vertical ? 'aria-orientation="vertical"' : ''}></div>`;
  }
}

customElements.define('diletta-divider', DilettaDivider);
export { DilettaDivider };
